from typing import List

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    # Build each term and join them
    result = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign
        if coeff < 0:
            sign = '-'
            abs_coeff = -coeff
        else:
            sign = '+' if result else ''
            abs_coeff = coeff

        # Build coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Build variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        result.append(sign + coeff_str + var_str)

    # If all coefficients are zero
    if not result:
        return '0'

    return ''.join(result)
