    # First, check if lengths are equal
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    # Check for contradictions: each encoded char must map to exactly one original char
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    # Check that the mapping is a permutation (each original char maps from exactly one encoded char)
    # Actually, we need to check that no two different encoded chars map to the same original char
    seen_originals = set()
    for enc_char, orig_char in mapping.items():
        if orig_char in seen_originals:
            return "Failed"
        seen_originals.add(orig_char)

    # Also, we need to ensure that all letters in the message can be decoded
    # The problem says "not all letters are represented in the mapping" - but this likely means
