def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for name, stmts in statements.items():
        is_liar = name in liar_count
        for stmt in stmts:
            # Skip statements about days of the week
            if any(day in stmt for day in days_of_week):
                continue

            # Parse the statement to determine its truth value
            # Statement formats observed: "I am guilty.", "ALICE is not guilty."
            stmt = stmt.strip()

            if "not guilty" in stmt:
                # Statement like "ALICE is not guilty."
                # Extract the subject
                subject = stmt.split(" is not guilty")[0].strip()
                if subject == "I":
                    subject = name
                # The statement claims that 'subject' is not guilty
                # Truth value: subject is not the criminal in this scenario
                actual_truth = (subject != scenario)
            elif "guilty" in stmt:
                # Statement like "I am guilty." or "ALICE is guilty."
                if "I am guilty" in stmt:
                    subject = name
                else:
                    subject = stmt.split(" is guilty")[0].strip()
                # The statement claims that 'subject' is guilty
                actual_truth = (subject == scenario)
            else:
                # Unknown statement format, assume it's irrelevant or treat as true if not false
                # For safety, if we can't parse, we might skip or assume consistent
                # However, based on problem description, we focus on guilt statements
                # Let's assume if it doesn't match known patterns, it's not a contradiction
                continue

            # If the speaker is a liar, their statement must be false
            # If the speaker is a truth-teller, their statement must be true
            if is_liar:
                if actual_truth:
                    return False
            else:
                if not actual_truth:
                    return False
    return True
