def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Calculate the longest increasing subsequence from the left
    inc = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Calculate the longest decreasing subsequence from the right
    dec = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if heights[j] < heights[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # The longest choir formation is the maximum length of inc[i] + dec[i] - 1
    # (subtract 1 because the peak at position i is counted in both)
    max_formation_length = max(inc[i] + dec[i] - 1 for i in range(n))

    # The minimum number of students that need to leave is the total minus the maximum formation length
    return n - max_formation_length
